window.__T__=[{"i":7360,"text":"{\n  \"type\": \"电商直播截图样机\",\n  \"scene\": {\n    \"subject\": \"{argument name=\\\"main subject\\\" default=\\\"外貌酷似 Sam Altman 的白人男性\\\"}\",\n    \"clothing\": \"深绿色圆领毛衣\",\n    \"action\": \"一只手拿着黑色产品盒，另一只手指向它\",\n    \"setting\": \"暗色调摄影棚，左侧配有麦克风，背景有淡淡的 'AI' 文字\",\n    \"props\": [\n      \"印有白色 OpenAI 标志的黑色马克杯\",\n      \"右侧堆叠着 4 个黑色产品盒\"\n    ]\n  },\n  \"product_design\": {\n    \"box_color\": \"黑色\",\n    \"logo\": \"橙色星号或太阳光芒图案\",\n    \"text\": \"{argument name=\\\"product name\\\" default=\\\"Claude Opus 4.7\\\"}\"\n  },\n  \"ui_overlays\": {\n    \"top_left_product_info\": {\n      \"brand_tag\": \"Anthropic 官方旗舰店\",\n      \"title\": \"{argument name=\\\"product name\\\" default=\\\"Claude Opus 4.7\\\"}\",\n      \"subtitle\": \"{argument name=\\\"main headline\\\" default=\\\"更强推理·更高智能\\\"}\",\n      \"sub_subtitle\": \"最强大模型: Opus 4.7 重磅发布!\",\n      \"bullet_points_count\": 3,\n      \"bullet_points\": [\"超强推理能力\", \"代码能力巅峰\", \"复杂任务轻松搞定\"]\n    },\n    \"top_right_live_status\": {\n      \"viewer_info\": \"直播中 | 52.8 万人观看\",\n      \"promo_banner\": \"直播专属福利 限时折扣·错过不再有\",\n      \"countdown\": \"倒计时 00:09:47\"\n    },\n    \"middle_right_price_card\": {\n      \"header\": \"{argument name=\\\"product name\\\" default=\\\"Claude Opus 4.7\\\"} 直播间专享价\",\n      \"price_currency\": \"¥\",\n      \"price_value\": \"{argument name=\\\"promotional price\\\" default=\\\"0.47\\\"}\",\n      \"price_unit\": \"/百万 tokens 起\",\n      \"original_price\": \"原价: ¥1.89\",\n      \"button\": \"立即抢购\"\n    },\n    \"bottom_left_chat\": {\n      \"message_count\": 9,\n      \"input_box_placeholder\": \"说点什么...\"\n    },\n    \"bottom_right_banner\": {\n      \"headline\": \"奥特曼首推！认准 Claude Opus 4.7\",\n      \"subheadline\": \"更智能 · 更安全 · 更可靠\",\n      \"feature_tags_count\": 4,\n      \"feature_tags\": [\"强大推理\", \"代码神器\", \"安全可靠\", \"极速响应\"]\n    },\n    \"floating_elements\": [\n      {\n        \"type\": \"sticker\",\n        \"position\": \"产品盒右侧上方\",\n        \"text\": \"{argument name=\\\"sticker text\\\" default=\\\"史上最强 AI 模型!\\\"}\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13995.jpg"]},{"i":7361,"text":"{\n  \"type\": \"2x2 广告网格\",\n  \"layout\": {\n    \"grid_structure\": \"2 行，2 列\",\n    \"sections\": [\n      {\n        \"position\": \"左上\",\n        \"theme\": \"护肤美妆广告\",\n        \"visuals\": \"一位年轻亚洲女性的肖像，皮肤透亮，手轻触脸颊。前景摆放着两瓶优雅的磨砂玻璃护肤品。\",\n        \"copy\": {\n          \"headline\": \"{argument name=\\\"skincare headline\\\" default=\\\"透明感、満ちる。\\\"}\",\n          \"subheadline\": \"当你的肌肤改变，你的生活也会随之改变。\",\n          \"brand_text\": \"全新抗衰老系列首发 {argument name=\\\"skincare brand\\\" default=\\\"SUIREN\\\"}\",\n          \"badge\": \"6.1 新品首发\"\n        }\n      },\n      {\n        \"position\": \"右上\",\n        \"theme\": \"旅行社宣传广告\",\n        \"visuals\": \"一位身穿白衬衫、戴着草帽的女性背影，眺望着风景如画的欧洲湖畔小镇，背景是山脉和教堂尖顶。天空中有一架小型飞机插画。\",\n        \"copy\": {\n          \"english_script\": \"Find your Journey\",\n          \"headline\": \"{argument name=\\\"travel headline\\\" default=\\\"心が動く旅へ。\\\"}\",\n          \"subheadline\": \"未见的风景正在等待着你。\",\n          \"badge\": \"限时优惠！6 月 30 日前最高可享 8 折\",\n          \"bottom_bar\": \"初夏欧洲行活动 | 点击查看详情 >\"\n        }\n      },\n      {\n        \"position\": \"左下\",\n        \"theme\": \"传统食品广告\",\n        \"visuals\": \"特写镜头：一碗质朴的白米饭，上面撒着鲣鱼片，放着一颗鲜亮的橙色生蛋黄。深色的酱油或高汤正从一个小陶瓷壶中倒入。左下角放着一个牛皮纸包装袋。\",\n        \"copy\": {\n          \"headline\": \"{argument name=\\\"food headline\\\" default=\\\"毎日のごはんを、もっと美味しく。\\\"}\",\n          \"product_name\": \"日常高汤\",\n          \"features\": \"无添加化学调味料或防腐剂 | 还原食材的纯粹鲜味。\",\n          \"badge\": \"内含 30 包高汤包\"\n        }\n      },\n      {\n        \"position\": \"右下\",\n        \"theme\": \"金融科技投资 App 广告\",\n        \"visuals\": \"一部现代智能手机，屏幕显示着金融仪表盘，包含蓝色折线图和投资组合明细。背景为干净的白色和浅蓝色。\",\n        \"copy\": {\n          \"logo\": \"M MoneyPath\",\n          \"headline\": \"为了未来的自己，{argument name=\\\"finance headline\\\" default=\\\"今はじめる資産形成\\\"}\",\n          \"subheadline\": \"简单易用的投资 App，新手也能安心使用\",\n          \"badge\": \"新用户注册即送 1,000 日元积分！\",\n          \"bottom_features\": [\n            \"100 日元起投\",\n            \"行业最低费率水平\",\n            \"支持 NISA\",\n            \"立即免费开户 >\"\n          ]\n        }\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13996.jpg"]},{"i":7362,"text":"{\n  \"type\": \"2x2 日式广告海报网格\",\n  \"layout\": {\n    \"format\": \"2x2 网格\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"theme\": \"护肤品牌\",\n        \"visual\": \"一位留着短黑发、皮肤水润透亮的年轻日本女性特写。左下角摆放着 3 瓶极简风格的白色护肤品。\",\n        \"text_elements\": {\n          \"headline\": \"{argument name=\\\"skincare headline\\\" default=\\\"素肌が、いちばんのメイクになる。\\\"}\",\n          \"brand\": \"urala\",\n          \"subtext\": [\"肌本来の力を引き出す 新・スキンケアシリーズ誕生\", \"4.25 NEW DEBUT\", \"うららかに、わたしらしく。\"]\n        }\n      },\n      {\n        \"position\": \"右上\",\n        \"theme\": \"咖啡馆推广\",\n        \"visual\": \"盘子里放着一片涂有草莓酱和黄油的厚吐司，旁边是一杯黑咖啡，放在窗边的木桌上。\",\n        \"text_elements\": {\n          \"headline\": \"{argument name=\\\"cafe headline\\\" default=\\\"今日も、いい日。\\\"}\",\n          \"brand\": \"morino cafe\",\n          \"subtext\": [\"森のそばの小さなカフェ\", \"こだわりのコーヒーと、焼きたてのパンでほっとひと息しませんか？\", \"季節限定 いちごのジャムトースト始めました\"]\n        }\n      },\n      {\n        \"position\": \"左下\",\n        \"theme\": \"个人健身房\",\n        \"visual\": \"一位扎着马尾辫、穿着黑色运动内衣的健美日本女性，在紫色灯光的健身房里坚定地向上看。\",\n        \"text_elements\": {\n          \"headline\": \"{argument name=\\\"gym headline\\\" default=\\\"わたしを超えていけ。\\\"}\",\n          \"brand\": \"BEYOND LIMIT PERSONAL GYM\",\n          \"subtext\": [\"今こそ、理想の自分へ\", \"まずは体験から！ 体験トレーニング 60分 ¥2,200(税込)\"]\n        }\n      },\n      {\n        \"position\": \"右下\",\n        \"theme\": \"度假胜地\",\n        \"visual\": \"从现代白色阳台望去，可以看到湛蓝的海洋和天空，阳台上摆放着一张小沙发和一盆植物。\",\n        \"text_elements\": {\n          \"headline\": \"{argument name=\\\"resort headline\\\" default=\\\"まだ見ぬ景色に、出会う旅。\\\"}\",\n          \"brand\": \"UMI to SORA RESORT\",\n          \"subtext\": [\"心がほどける、特別な時間をあなたに。\", \"期間限定 夏のご予約キャンペーン\", \"{argument name=\\\"resort discount\\\" default=\\\"最大20%OFF\\\"}\"]\n        }\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/13997.jpg"]},{"i":7363,"text":"{\n  \"type\": \"演示文稿信息图\",\n  \"style\": {\n    \"theme\": \"{argument name=\\\"theme color\\\" default=\\\"霓虹蓝\\\"}\",\n    \"background\": \"{argument name=\\\"background style\\\" default=\\\"深蓝色未来科技风，带有发光数据流和上升箭头\\\"}\"\n  },\n  \"header\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"核心抓手\\\"}\",\n    \"subtitle\": \"{argument name=\\\"english title\\\" default=\\\"Key Levers\\\"}\",\n    \"description\": \"构建可复制、可放大、可持续的增长引擎\"\n  },\n  \"layout\": {\n    \"type\": \"循环流程图\",\n    \"center_node\": {\n      \"title\": \"{argument name=\\\"center node title\\\" default=\\\"P7 核心系统\\\"}\",\n      \"subtitle\": \"战略落地 · 高效执行 · 持续进化\",\n      \"visual\": \"发光科技球体\"\n    },\n    \"surrounding_nodes\": {\n      \"count\": 5,\n      \"connection\": \"形成顺时针循环的发光蓝色箭头\",\n      \"nodes\": [\n        {\n          \"position\": \"top\",\n          \"icon\": \"机械臂\",\n          \"english_label\": \"Automation Pipeline\",\n          \"chinese_label\": \"自动化\",\n          \"description\": \"减少人工干预，提升交付效率\"\n        },\n        {\n          \"position\": \"right\",\n          \"icon\": \"带有图表的显示器\",\n          \"english_label\": \"Data Feedback Loop\",\n          \"chinese_label\": \"数据驱动\",\n          \"description\": \"数据洞察，持续优化决策\"\n        },\n        {\n          \"position\": \"bottom right\",\n          \"icon\": \"带有勾选标记的剪贴板\",\n          \"english_label\": \"Standardization\",\n          \"chinese_label\": \"标准化\",\n          \"description\": \"统一规范，降低复杂度\"\n        },\n        {\n          \"position\": \"bottom left\",\n          \"icon\": \"硬币\",\n          \"english_label\": \"Cost Efficiency\",\n          \"chinese_label\": \"成本优化\",\n          \"description\": \"资源精准投入，效益最大化\"\n        },\n        {\n          \"position\": \"left\",\n          \"icon\": \"堆叠立方体\",\n          \"english_label\": \"Reusable Components\",\n          \"chinese_label\": \"模块化\",\n          \"description\": \"复用加速，质量一致\"\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14000.jpg"]},{"i":7364,"text":"{\n  \"type\": \"2x2 日式广告横幅网格\",\n  \"layout\": {\n    \"grid_size\": \"2x2\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"industry\": \"护肤化妆品\",\n        \"visuals\": \"一位皮肤清透、散发光泽的年轻亚洲女性轻触脸部的肖像。两瓶贴有“SUIREN”标签的时尚银白色化妆品瓶/罐。\",\n        \"typography\": {\n          \"badge\": \"6.1 新品发布\",\n          \"main_copy\": \"{argument name=\\\"skincare catchphrase\\\" default=\\\"透明感、満ちる。\\\"}\",\n          \"sub_copy\": \"肌肤改变，生活随之改变。\",\n          \"brand_text\": \"全新抗衰老系列 SUIREN -睡莲- 诞生\"\n        }\n      },\n      {\n        \"position\": \"右上\",\n        \"industry\": \"旅行社\",\n        \"visuals\": \"一位戴着草帽、身穿白衬衫的女性背影，眺望着风景如画的欧洲湖畔小镇和群山。画面中有一条手绘的小飞机航迹。\",\n        \"typography\": {\n          \"english_script\": \"Find your Journey\",\n          \"main_copy\": \"{argument name=\\\"travel catchphrase\\\" default=\\\"心が動く旅へ。\\\"}\",\n          \"sub_copy\": \"未曾见过的风景，正在等待着你。\",\n          \"discount_badge\": \"黄色圆圈，文字为“限时特惠！最高 20% OFF，截止至 6.30”\",\n          \"footer_bar\": \"深蓝色横条，带有“初夏欧洲之旅活动”字样及“了解详情 >”按钮\"\n        }\n      },\n      {\n        \"position\": \"左下\",\n        \"industry\": \"食品\",\n        \"visuals\": \"特写镜头：一碗撒有鲣鱼干和生蛋黄的蓬松白米饭。深色酱油正从一个小陶瓷壶中倒出。背景是一个带有蓝色波浪图案的自立袋包装。\",\n        \"typography\": {\n          \"main_copy\": \"{argument name=\\\"food catchphrase\\\" default=\\\"毎日のごはんを、もっと美味しく。\\\"}\",\n          \"product_name\": \"日常高汤包\",\n          \"sub_copy\": \"无化学调味料、无防腐剂，保留食材原汁原味。\",\n          \"badge\": \"高汤包 30 袋装\"\n        }\n      },\n      {\n        \"position\": \"右下\",\n        \"industry\": \"金融科技 App\",\n        \"visuals\": \"一部现代智能手机，屏幕显示带有蓝色折线图和投资组合分析的金融仪表板 UI。整体采用简洁的白蓝配色。\",\n        \"typography\": {\n          \"logo\": \"M {argument name=\\\"finance app name\\\" default=\\\"MoneyPath\\\"}\",\n          \"main_copy\": \"为了未来的自己，{argument name=\\\"finance catchphrase\\\" default=\\\"今はじめる資産形成\\\"}\",\n          \"sub_copy\": \"新手也能安心使用的极简投资 App\",\n          \"promo_badge\": \"带有礼品图标的蓝色圆圈，文字为“新用户注册即送 1,000 日元积分！”\",\n          \"footer_features\": \"蓝色横条，包含 4 个不同的图标和详细说明 App 优势的文字块\"\n        }\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14001.jpg"]},{"i":7365,"text":"{\n  \"type\": \"2x2 数字广告横幅网格\",\n  \"style\": \"专业、现代、高质量商业平面设计，日式排版\",\n  \"layout\": {\n    \"grid\": \"2 列，2 行\",\n    \"banners\": [\n      {\n        \"position\": \"左上\",\n        \"industry\": \"室内设计 / 住宅\",\n        \"visuals\": \"明亮、现代的客厅，配有米色沙发、木制餐桌、大窗户和室内绿植。\",\n        \"typography\": {\n          \"headline\": \"{argument name=\\\"home banner headline\\\" default=\\\"理想の暮らし、デザインしよう。\\\"}\",\n          \"logo\": \"NATURAL HOME\"\n        },\n        \"ui_elements\": [\n          \"绿色圆形徽章：'相談・見積もり無料'\",\n          \"绿色右下角三角形按钮：'資料請求はこちらから ▶'\"\n        ]\n      },\n      {\n        \"position\": \"右上\",\n        \"industry\": \"护肤品 / 化妆品\",\n        \"visuals\": \"一位皮肤清透的女性肖像，手触脸颊，旁边是一瓶带有水花效果的 'Solea MOISTURE SERUM'。\",\n        \"typography\": {\n          \"headline\": \"{argument name=\\\"skincare banner headline\\\" default=\\\"うるおい、満ちる。透明感。\\\"}\",\n          \"subheadline\": \"敏感肌にもやさしい\"\n        },\n        \"ui_elements\": [\n          \"3 个浅蓝色圆形功能徽章：'無添加処方', '高保湿', '低刺激'\",\n          \"纯蓝色底部横幅：'今なら初回限定 20%OFF'\"\n        ],\n        \"feature_count\": 3\n      },\n      {\n        \"position\": \"左下\",\n        \"industry\": \"美食外送\",\n        \"visuals\": \"深色背景。一张诱人的汉堡排配蔬菜大图。下方有 3 张较小的方形照片：意大利面、切片牛排沙拉和巧克力蛋糕。\",\n        \"typography\": {\n          \"headline\": \"{argument name=\\\"food banner headline\\\" default=\\\"おうちで楽しむプレミアムグルメ\\\"}\"\n        },\n        \"ui_elements\": [\n          \"3 个带文字的功能图标：'有名店の味を冷凍でお届け', '簡単調理で本格的な美味しさ', '特別な日のごちそうに'\",\n          \"金色底部横幅：'初回限定 1,000円OFF'\"\n        ],\n        \"feature_count\": 3,\n        \"thumbnail_count\": 3\n      },\n      {\n        \"position\": \"右下\",\n        \"industry\": \"在线教育 / 英语课程\",\n        \"visuals\": \"一位面带微笑的年轻日本女性戴着耳机，对着笔记本电脑屏幕挥手。\",\n        \"typography\": {\n          \"headline\": \"{argument name=\\\"english banner headline\\\" default=\\\"英会話で、新しい自分に。\\\"}\",\n          \"highlighted_text\": \"マンツーマンのオンラインレッスン\"\n        },\n        \"ui_elements\": [\n          \"3 个带文字的功能图标：'24時間予約可能', '初心者でも安心', '講師は全員ネイティブ'\",\n          \"带有 'English+' 标志的蓝色底部横幅：'{argument name=\\\"english discount text\\\" default=\\\"初月 50% OFF\\\"}'\"\n        ],\n        \"feature_count\": 3\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14002.jpg"]},{"i":7366,"text":"一张电影质感的科幻动画电影海报，画面中是一台高耸入云、历经战火的 {argument name=\"mecha color\" default=\"白色\"} 机甲，带有发光的红色装饰和复杂的机械细节，伫立在破败的工业城市废墟中。前景中，一位 {argument name=\"pilot description\" default=\"留着黑发、身穿黑色流线型驾驶服的年轻男性动画角色\"} 自信地站立着，手中拿着头盔。驾驶员和机甲的肩部都印有数字“08”。背景展示了戏剧性的日落天空，乌云密布，废墟中烟雾缭绕，无人机在空中盘旋，地面湿润且带有倒影。海报顶部是一句标语：“{argument name=\"top tagline\" default=\"守護の名で生まれ、破壊の命で目覚めた。\"}”。底部是一个醒目且优雅的衬线体主标题：“{argument name=\"main title\" default=\"鋼鉄の盾\"}”，下方配有英文副标题“S T E E L  S H I E L D”。在最底部的边缘，有一行较小的文字：“{argument name=\"bottom tagline\" default=\"2096年、東京湾岸第八埋立層。最後の防衛機兵、反逆起動。\"}”。整体氛围宏大、具有反乌托邦色彩且细节丰富。","imgs":["https://r2.qqsrc.com/images/originals/14003.jpg"]},{"i":7367,"text":"{\n  \"type\": \"企业演示 Slides 信息图\",\n  \"style\": \"深色模式，未来感，高科技 HUD，发光光纤线条，{argument name=\\\"theme color\\\" default=\\\"霓虹蓝与青色\\\"}\",\n  \"header\": {\n    \"position\": \"左上角\",\n    \"title_chinese\": \"{argument name=\\\"main title\\\" default=\\\"赋能体系\\\"}\",\n    \"title_english\": \"{argument name=\\\"english title\\\" default=\\\"Enablement System\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"从个人能力到组织能力，放大影响力\\\"}\"\n  },\n  \"layout\": {\n    \"centerpiece\": {\n      \"description\": \"发光球形基座\",\n      \"title\": \"{argument name=\\\"platform name\\\" default=\\\"核心赋能平台\\\"}\",\n      \"subtitle\": \"ENABLEMENT PLATFORM\",\n      \"inner_cards_count\": 2,\n      \"inner_cards\": [\n        {\n          \"icon\": \"层叠方块\",\n          \"title\": \"平台能力 Platform\",\n          \"details\": \"基础设施 | 服务能力 | 数据资产 | 统一标准\"\n        },\n        {\n          \"icon\": \"扳手与代码括号\",\n          \"title\": \"工具链 Tooling\",\n          \"details\": \"自动化 | 可视化 | CI/CD | 智能化\"\n        }\n      ],\n      \"bottom_label\": \"沉淀 · 标准化 · 可复制\"\n    },\n    \"surrounding_nodes_count\": 4,\n    \"surrounding_nodes\": [\n      {\n        \"position\": \"左上\",\n        \"label\": \"提效团队 A\",\n        \"icon\": \"三人剪影\",\n        \"metric\": \"交付提效 +35%\"\n      },\n      {\n        \"position\": \"左下\",\n        \"label\": \"提效团队 B\",\n        \"icon\": \"三人剪影\",\n        \"metric\": \"质量提升 -28% 缺陷率\"\n      },\n      {\n        \"position\": \"右上\",\n        \"label\": \"提效团队 C\",\n        \"icon\": \"三人剪影\",\n        \"metric\": \"成本优化 -20% 资源成本\"\n      },\n      {\n        \"position\": \"右下\",\n        \"label\": \"提效团队 D\",\n        \"icon\": \"三人剪影\",\n        \"metric\": \"能力提升 新人成长加速 50%\"\n      }\n    ],\n    \"footer_sections_count\": 3,\n    \"footer_sections\": [\n      {\n        \"icon\": \"折线图\",\n        \"title\": \"降低门槛\",\n        \"description\": \"统一标准与工具，让优秀实践触手可及\"\n      },\n      {\n        \"icon\": \"柱状图\",\n        \"title\": \"提高产出\",\n        \"description\": \"赋能团队，释放潜力，实现组织效能跃升\"\n      },\n      {\n        \"icon\": \"奖杯\",\n        \"title\": \"放大影响力\",\n        \"description\": \"从执行者到赋能者，构建可持续的组织能力\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14005.jpg"]},{"i":7368,"text":"{\n  \"type\": \"广告概念项目\",\n  \"layout\": {\n    \"style\": \"{argument name=\\\"grid layout style\\\" default=\\\"2x2 日式广告海报网格\\\"}\",\n    \"sections\": [\n      {\n        \"position\": \"左上\",\n        \"industry\": \"科技\",\n        \"subject\": \"悬浮在干净表面上的白色无线耳机\",\n        \"style\": \"极简、明亮、白色背景、时尚\",\n        \"headline\": \"{argument name=\\\"tech ad headline\\\" default=\\\"次世代サコンド、ここからはじまる\\\"}\",\n        \"brand_logo\": \"aura+\"\n      },\n      {\n        \"position\": \"右上\",\n        \"industry\": \"美妆\",\n        \"subject\": \"粉色唇膏和打开的化妆粉饼盒，置于反光表面上\",\n        \"style\": \"优雅、暖光、柔和的背景虚化、奢华\",\n        \"headline\": \"{argument name=\\\"cosmetics ad headline\\\" default=\\\"ひと塗りで、私が変わる。\\\"}\",\n        \"brand_logo\": \"LUMINA\"\n      },\n      {\n        \"position\": \"左下\",\n        \"industry\": \"饮料\",\n        \"subject\": \"银蓝色能量饮料罐，周围环绕着飞溅的水花和闪电\",\n        \"style\": \"动感、高对比度、深色背景、充满活力\",\n        \"headline\": \"{argument name=\\\"energy drink headline\\\" default=\\\"限界を、もう一歩先へ。\\\"}\",\n        \"brand_logo\": \"aura+\"\n      },\n      {\n        \"position\": \"右下\",\n        \"industry\": \"旅游\",\n        \"subject\": \"行驶在绿色稻田中的地方列车，背景为群山\",\n        \"style\": \"风景优美、日落光影、温暖、怀旧\",\n        \"headline\": \"{argument name=\\\"travel ad headline\\\" default=\\\"週末、小さな旅に出かけよう。\\\"}\",\n        \"brand_logo\": \"東都ライン\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14006.jpg"]},{"i":7369,"text":"{\n  \"type\": \"印刷版日本报纸页面的照片\",\n  \"style\": \"逼真的新闻纸质感，轻微倾斜的俯拍视角，自然光，纸张有轻微褶皱\",\n  \"header\": {\n    \"date\": \"{argument name=\\\"date\\\" default=\\\"2026 年（令和 8 年）4 月 23 日 星期四\\\"}\",\n    \"newspaper_name\": \"{argument name=\\\"newspaper name\\\" default=\\\"朝日新闻\\\"}\",\n    \"publisher_info\": \"发行所：朝日新闻东京本社\",\n    \"top_right_ad\": \"水与生活 SUNTORY\"\n  },\n  \"main_headlines\": [\n    \"{argument name=\\\"main headline 1\\\" default=\\\"OpenAI 发布新模型“Spud”\\\"}\",\n    \"{argument name=\\\"main headline 2\\\" default=\\\"“Codex SuperApp”同步公开\\\"}\"\n  ],\n  \"sub_headline_bar\": \"在网络攻击与编码性能方面全面超越现有基准测试\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"position\": \"中左\",\n        \"type\": \"文章文本栏\",\n        \"content\": \"日语新闻文本\"\n      },\n      {\n        \"position\": \"中央\",\n        \"type\": \"嵌入式图像\",\n        \"description\": \"展示 3 个手机 UI 模拟图的深蓝色图形\",\n        \"overlay_text\": \"{argument name=\\\"center image text\\\" default=\\\"Codex SuperApp\\\"}\",\n        \"caption\": \"Codex SuperApp 概念图（由 OpenAI 提供）\"\n      },\n      {\n        \"position\": \"中右\",\n        \"type\": \"竖排文本标题\",\n        \"text\": \"“作为 AGI 时代的基石”开发竞争愈演愈烈\"\n      }\n    ]\n  },\n  \"lower_section\": {\n    \"headline\": \"“压倒性的进步”专家给予高度评价\",\n    \"columns\": 3,\n    \"left_column\": {\n      \"title\": \"■主要特征\",\n      \"bullet_points_count\": 3\n    },\n    \"middle_column\": \"日语文章文本\",\n    \"right_column\": \"日语文章文本\"\n  },\n  \"footer_teasers\": {\n    \"count\": 3,\n    \"labels\": [\n      \"关税谈判：日美将重新协商\",\n      \"九州地区遭遇大雨，2 人受伤\",\n      \"观点\"\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14008.jpg"]},{"i":7370,"text":"一幅令人惊叹的 {argument name=\"setting\" default=\"奇幻沿海城市\"} 全景图。画面主体是一座 {argument name=\"prominent landmark\" default=\"山顶上的大型石砌城堡\"}，俯瞰着湛蓝的海洋。城堡下方是一个繁华的城镇，拥有 {argument name=\"architecture style\" default=\"欧洲半木结构房屋\"} 和棕色屋顶，掩映在郁郁葱葱的树木和棕榈树丛中。一条清澈的绿松石色小河穿过城镇中心，河岸边是石砌码头、沙滩和小型木船。远处，几艘大型帆船在深蓝色的海面上航行。天空晴朗湛蓝，点缀着朵朵白云，呈现出 {argument name=\"time of day\" default=\"明媚晴天\"} 的景象。整体美学风格为 {argument name=\"art style\" default=\"高度精细的数字插画，经典 RPG 概念艺术\"}，色彩鲜艳，建筑细节错综复杂。","imgs":["https://r2.qqsrc.com/images/originals/14009.jpg"]},{"i":7371,"text":"{\n  \"type\": \"企业演示 Slides\",\n  \"theme\": \"高科技、未来感、深色模式、发光霓虹蓝与紫色点缀、抽象数字粒子波背景\",\n  \"header\": {\n    \"title_primary\": \"{argument name=\\\"main chinese title\\\" default=\\\"业务影响\\\"}\",\n    \"title_secondary\": \"{argument name=\\\"main english title\\\" default=\\\"Business Impact\\\"}\",\n    \"tagline\": \"{argument name=\\\"tagline\\\" default=\\\"用数据说话，用结果证明价值\\\"}\"\n  },\n  \"layout\": {\n    \"left_section\": {\n      \"type\": \"折线图\",\n      \"title\": \"效率与产能提升趋势\",\n      \"y_axis\": [\"0%\", \"100%\", \"200%\", \"300%\", \"400%\", \"500%\", \"600%\"],\n      \"x_axis\": [\"Q1\", \"Q2\", \"Q3\", \"Q4\", \"现在\"],\n      \"lines\": [\n        {\n          \"label\": \"交付效率 (相对值)\",\n          \"color\": \"霓虹蓝\",\n          \"trend\": \"上升曲线\",\n          \"annotation\": \"效率持续提升\"\n        },\n        {\n          \"label\": \"单位成本 (相对值)\",\n          \"color\": \"霓虹紫\",\n          \"trend\": \"下降曲线\",\n          \"annotation\": \"成本显著下降\"\n        }\n      ]\n    },\n    \"right_section\": {\n      \"type\": \"KPI 网格\",\n      \"count\": 4,\n      \"arrangement\": \"2x2 网格\",\n      \"cards\": [\n        {\n          \"icon\": \"火箭\",\n          \"title\": \"效率提升\",\n          \"value\": \"{argument name=\\\"kpi 1 value\\\" default=\\\"+120%\\\"}\",\n          \"subtext\": \"交付效率显著提升\"\n        },\n        {\n          \"icon\": \"带有向下箭头的硬币\",\n          \"title\": \"成本降低\",\n          \"value\": \"{argument name=\\\"kpi 2 value\\\" default=\\\"-200%\\\"}\",\n          \"subtext\": \"单位交付成本下降\"\n        },\n        {\n          \"icon\": \"带有向上箭头的柱状图\",\n          \"title\": \"产能提升\",\n          \"value\": \"5 倍\",\n          \"subtext\": \"团队整体产能跃升\"\n        },\n        {\n          \"icon\": \"人群\",\n          \"title\": \"覆盖团队\",\n          \"value\": \"10 个\",\n          \"subtext\": \"业务团队规模化受益\"\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14011.jpg"]},{"i":7372,"text":"一张照片级真实感的抓拍照片，展示了两位亚裔女性在拥挤的 {argument name=\"store type\" default=\"复古服装店\"} 内一起购物。左侧的女性扎着棕色头发，身穿 {argument name=\"left woman outfit\" default=\"白色罗纹短款上衣和破洞牛仔短裤\"}，背着一个米色单肩包。她正用木制衣架举起一件 {argument name=\"item being examined\" default=\"带有精致金色刺绣的深蓝色缎面纪念夹克\"}。右侧的女性梳着凌乱的丸子头，身穿 {argument name=\"right woman outfit\" default=\"塞进高腰蓝色牛仔裤里的白色印花 T 恤\"}，正赞赏地看着这件夹克。她们站在狭窄的过道中，两侧是堆满彩色服装的货架，天花板上也挂满了衣服。场景呈现出 {argument name=\"lighting and atmosphere\" default=\"温暖、略显昏暗的环境光，背景带有浅景深模糊效果\"}。","imgs":["https://r2.qqsrc.com/images/originals/14012.jpg"]},{"i":7373,"text":"{\n  \"type\": \"Logo 概念展示表\",\n  \"theme\": \"{argument name=\\\"行业主题\\\" default=\\\"AI 教育学校\\\"}\",\n  \"color_palette\": \"{argument name=\\\"主色调\\\" default=\\\"薄荷绿\\\"} 渐变色，深灰色文字，白色背景\",\n  \"layout\": {\n    \"grid\": \"2 行 3 列\",\n    \"count\": 6,\n    \"common_elements\": [\n      \"图形标志\",\n      \"主标题：{argument name=\\\"公司名称\\\" default=\\\"株式会社エヌイチ\\\"}\",\n      \"副标题：关于 AI 与学习的独特日文副标题\"\n    ],\n    \"variants\": [\n      { \"position\": \"左上\", \"mark\": \"带有 4 点星光的圆润“Ni”字样\" },\n      { \"position\": \"中上\", \"mark\": \"被轨道环交叉的衬线体“N1”\" },\n      { \"position\": \"右上\", \"mark\": \"形成“N1”形状的打开书籍，带有分散的数字像素\" },\n      { \"position\": \"左下\", \"mark\": \"带有圆点并由圆形轮廓包裹的“N1”\" },\n      { \"position\": \"中下\", \"mark\": \"左腿呈现数字点阵效果的几何体“N1”\" },\n      { \"position\": \"右下\", \"mark\": \"包含萌芽植物和星光的人头轮廓\" }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14013.jpg"]},{"i":7374,"text":"{\n  \"type\": \"印刷报纸头版的照片级真实感图像\",\n  \"setting\": \"放置在厨房台面上，背景为模糊的家电\",\n  \"newspaper_header\": {\n    \"title\": \"{argument name=\\\"newspaper name\\\" default=\\\"USA TODAY\\\"}\",\n    \"date\": \"{argument name=\\\"date\\\" default=\\\"04.23.26\\\"}\",\n    \"details\": \"全国新闻 | $3.00 | 星期四\",\n    \"top_right_teaser\": {\n      \"headline\": \"美国与菲律宾在南海举行联合演习\",\n      \"image\": \"海洋中的海军舰艇\"\n    }\n  },\n  \"layout\": {\n    \"element_counts\": {\n      \"articles_and_teasers\": 5,\n      \"printed_images\": 4\n    },\n    \"sections\": [\n      {\n        \"position\": \"顶部居中\",\n        \"type\": \"主文章\",\n        \"headline\": \"{argument name=\\\"main headline\\\" default=\\\"OpenAI 的新型 Spud 模型在网络战和编码基准测试中占据主导地位\\\"}\",\n        \"image\": \"{argument name=\\\"main image subject\\\" default=\\\"一只戴着皇冠的 3D 蓝鲸，带有 'spud by OpenAI' 字样\\\"}\",\n        \"columns\": 2\n      },\n      {\n        \"position\": \"右侧栏顶部\",\n        \"type\": \"侧边文章\",\n        \"headline\": \"科技股财报利好，股市上涨\",\n        \"columns\": 1\n      },\n      {\n        \"position\": \"底部居中\",\n        \"type\": \"次要文章\",\n        \"headline\": \"{argument name=\\\"secondary headline\\\" default=\\\"Codex 应用作为‘万能超级应用’发布\\\"}\",\n        \"image\": \"显示带有 'codex' 字样应用界面的智能手机\",\n        \"columns\": 3\n      },\n      {\n        \"position\": \"右侧栏底部\",\n        \"type\": \"侧边文章\",\n        \"headline\": \"亚马逊发现新鸟类物种\",\n        \"columns\": 1\n      },\n      {\n        \"position\": \"底部边缘\",\n        \"type\": \"页脚预告\",\n        \"headline\": \"NFL 选秀爆冷：四分卫跌至第二轮\",\n        \"image\": \"美式足球运动员\"\n      }\n    ]\n  },\n  \"photography_style\": \"俯视角度，自然光，可见纸张纹理和轻微折痕\"\n}","imgs":["https://r2.qqsrc.com/images/originals/14014.jpg"]},{"i":7375,"text":"{\n  \"type\": \"印刷报纸的照片级真实感摄影\",\n  \"style\": \"真实的纸张纹理，略带角度的俯视图，自然光效\",\n  \"header\": {\n    \"left_logo\": \"SHINSEGAE DUTY FREE\",\n    \"center_title\": \"{argument name=\\\"newspaper name\\\" default=\\\"韩国经济\\\"}\",\n    \"right_logo\": \"Myeongryun Jinsa Galbi\",\n    \"date\": \"{argument name=\\\"date\\\" default=\\\"2026 年 4 月 23 日 星期四\\\"}\"\n  },\n  \"headlines\": {\n    \"main\": \"{argument name=\\\"main headline\\\" default=\\\"OpenAI 发布下一代模型 'Spud'，横扫编码与网络战基准测试\\\"}\",\n    \"sub\": \"全新超级应用 'Codex' 同步上线……它会成为 AI 战争中的游戏规则改变者吗？\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"中心图形\",\n        \"position\": \"中间\",\n        \"text\": \"隆重推出 {argument name=\\\"app name\\\" default=\\\"Codex\\\"}，面向所有人的超级应用\",\n        \"ui_screens_count\": 3,\n        \"ui_screens_labels\": [\n          \"包含编写代码和数据分析等选项的菜单列表\",\n          \"带有紫色折线图的分析仪表盘\",\n          \"显示 Python 斐波那契函数的代码编辑器\"\n        ]\n      },\n      {\n        \"title\": \"文章栏\",\n        \"position\": \"中心图形周围\",\n        \"count\": 3,\n        \"labels\": [\n          \"带有文章正文的左栏\",\n          \"图形下方的中间栏\",\n          \"带有要点的右栏\"\n        ]\n      },\n      {\n        \"title\": \"底部区域\",\n        \"position\": \"底部\",\n        \"headline\": \"{argument name=\\\"bottom headline\\\" default=\\\"受 AI 涨势推动，纽约股市全线上扬……纳斯达克指数上涨 2.7%\\\"}\",\n        \"ad_box\": \"深蓝色方框，文字内容为：全球第一存储半导体公司三星电子\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14015.jpg"]},{"i":7376,"text":"一张写实、自然的抓拍照片，展示了两位年轻亚裔女性在拥挤的 {argument name=\"setting\" default=\"复古服装店\"} 内购物的场景。前景中的女性留着棕色马尾辫，身穿 {argument name=\"foreground outfit\" default=\"白色罗纹短款上衣和磨损感牛仔短裤\"}，背着一个米色单肩包。她正举起并仔细查看一件 {argument name=\"item being examined\" default=\"带有精致刺绣的蓝色缎面纪念夹克\"}。她身旁的第二位女性留着齐刘海，身穿 {argument name=\"background outfit\" default=\"白色 T 恤和牛仔背带裤\"}，正对着夹克露出温暖的笑容。店内挂满了色彩缤纷的复古服装，在温暖的氛围灯光下，背景中可以看到一块写着“VINTAGE”的木牌。浅景深效果聚焦于两位女性和那件夹克。","imgs":["https://r2.qqsrc.com/images/originals/14016.jpg"]},{"i":7377,"text":"一张 {argument name=\"photography style\" default=\"具有浅景深和柔和虚化效果的写实人像\"}，主角是一位 {argument name=\"subject\" default=\"年轻日本女性\"}，正回头看向镜头，脸上带着 {argument name=\"expression\" default=\"温柔的微笑\"}。她身着 {argument name=\"attire\" default=\"带有橙色枫叶图案的浅米色和服\"}，腰间系着金色腰带。深色长发盘成优雅的发髻，几缕发丝垂在脸颊旁，耳边戴着精致的珍珠耳环。背景设定为 {argument name=\"setting\" default=\"红叶绚烂的秋日庭院\"}，左上角点缀着鲜艳的红叶，背景经过深度虚化处理，营造出宁静而富有电影感的氛围。","imgs":["https://r2.qqsrc.com/images/originals/14017.jpg"]},{"i":7378,"text":"一张高端电影感商业摄影作品，画面中一位肌肉发达的人形香蕉角色正站在光线昏暗、氛围感十足的酒窖中。该角色拥有写实的黄色香蕉皮躯干、带有浓密黑眉和露齿大笑的卡通面孔，以及人类的肌肉手臂。他身穿红色围裙，优雅地端着一杯红酒。在他右侧的木质台面上放着一瓶深色玻璃红酒瓶，瓶身上贴着经典优雅的酒标，上面写有 {argument name=\"wine brand\" default=\"Maison Rouge B.\"} 以及一座城堡的插画。背景是模糊的酒架，陈列着各式红酒瓶，在深红色和棕色调的精致戏剧性灯光照射下显得格外高级。左上角以优雅的白色日文字体显示主标语 {argument name=\"main tagline\" default=\"その一杯に、理由はある。\"}，下方配有较小的副标题 {argument name=\"sub tagline\" default=\"甘さではなく、余韻で選ぶ。\"}。左下角有微小的法律声明文字“※お酒は20歳になってから”。右下角以简洁的衬线字体展示品牌名称 {argument name=\"wine brand\" default=\"Maison Rouge B.\"}。","imgs":["https://r2.qqsrc.com/images/originals/14018.jpg"]},{"i":7379,"text":"{\n  \"type\": \"宣传单\",\n  \"style\": \"简洁、医疗、专业、通透\",\n  \"color_palette\": [\"白色\", \"深绿色\", \"黑色\"],\n  \"layout\": {\n    \"hero\": {\n      \"headline\": \"{argument name=\\\"main headline\\\" default=\\\"了解身体真相的 2 周时间。\\\"}\",\n      \"subheadline\": \"{argument name=\\\"program name\\\" default=\\\"血糖监测项目\\\"}\",\n      \"image\": \"{argument name=\\\"hero image subject\\\" default=\\\"一位身穿白色 T 恤的亚洲女性微笑着，看向右上方，上臂佩戴着圆形的白色动态血糖监测传感器。背景明亮通透，带有模糊的植物。\\\"}\",\n      \"intro_text_paragraphs\": 4\n    },\n    \"middle_section\": {\n      \"box_title\": \"项目内容\",\n      \"checklist_count\": 7,\n      \"checklist_items\": [\n        \"Libre 传感器佩戴及专属 App 安装支持\",\n        \"饮食与生活习惯问询\",\n        \"血糖值学习资料\",\n        \"2 周血糖数据监测\",\n        \"中期反馈 (LINE)\",\n        \"最终反馈 (LINE)\",\n        \"个人血糖报告\"\n      ],\n      \"visuals\": [\n        \"显示血糖读数为 '112' 和绿色折线图的智能手机 UI 模型\",\n        \"深绿色圆形徽章，文字为 '通过数据洞察你的每一天。'\"\n      ]\n    },\n    \"bottom_section\": {\n      \"recommendations_title\": \"推荐人群\",\n      \"recommendations_count\": 3,\n      \"recommendations_items\": [\n        \"体检时被告知需要关注血糖值\",\n        \"注意饮食但数值没有改善\",\n        \"想了解适合自己的饮食方式\"\n      ],\n      \"pricing\": {\n        \"label\": \"费用\",\n        \"amount\": \"{argument name=\\\"price\\\" default=\\\"¥35,000\\\"}\",\n        \"note\": \"(含税，包含传感器费用)\"\n      }\n    },\n    \"footer\": {\n      \"background_color\": \"深绿色\",\n      \"provider\": \"{argument name=\\\"company name\\\" default=\\\"百岁制造所\\\"}\",\n      \"representative\": \"健康顾问 林 利生太\",\n      \"contact_info\": \"电话占位符及支持文本\",\n      \"badge\": \"圆形徽章，文字为 '欢迎随时咨询'\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14019.jpg"]},{"i":7380,"text":"{\n  \"type\": \"日本超市促销传单\",\n  \"theme\": \"春季庆典，樱花图案，鲜艳的红黄色调\",\n  \"header\": {\n    \"store_name\": \"{argument name=\\\"store name\\\" default=\\\"超市 架空\\\"}\",\n    \"main_title\": \"{argument name=\\\"main headline\\\" default=\\\"周末大感谢祭\\\"}\",\n    \"date\": \"{argument name=\\\"sale date\\\" default=\\\"4 月 19 日 (周日) 限定\\\"}\",\n    \"badges\": [\"积分卡 5 倍积分\", \"春季风味宣传语\"]\n  },\n  \"layout\": {\n    \"structure\": \"包含 12 个商品面板（3 行 4 列）的网格，以及右侧垂直侧边栏\",\n    \"product_panels\": {\n      \"count\": 12,\n      \"items\": [\n        \"春季卷心菜，红色价格标签 158\",\n        \"竹笋，红色价格标签 198\",\n        \"草莓，红色价格标签 598\",\n        \"樱饼，红色价格标签 398\",\n        \"活蛤蜊，红色价格标签 298\",\n        \"鲷鱼刺身，红色价格标签 580\",\n        \"牛肩肉，红色价格标签 1280\",\n        \"春卷食材，红色价格标签 780\",\n        \"新洋葱，红色价格标签 128\",\n        \"油菜花，红色价格标签 198\",\n        \"五花肉片，红色价格标签 228\",\n        \"樱花馒头，红色价格标签 168\"\n      ]\n    },\n    \"sidebar\": {\n      \"position\": \"右侧\",\n      \"section_count\": 4,\n      \"sections\": [\n        \"店铺地址、电话号码和营业时间\",\n        \"绿色项目符号列表展示店铺特色\",\n        \"带有停车信息的小型本地地图\",\n        \"绿色员工招聘横幅\"\n      ]\n    },\n    \"footer\": \"全宽红色横幅，配有白色促销文字和细则说明\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14020.jpg"]},{"i":7381,"text":"一张写实风格的城市广告海报，画面中一位身穿街头服饰的日本年轻女性正在繁忙的人行横道中央做深蹲。她戴着黑色针织帽，身穿深灰色超大款连帽衫，佩戴粗款银色项链，下身穿着橄榄绿工装裤，脚蹬米色与黑色拼接的厚底运动鞋。她正向镜头展示两罐一模一样的能量饮料；罐身为银黑配色，印有醒目的黄色闪电标志和文字 {argument name=\"can logo text\" default=\"ENERGY\"}。背景是模糊且熙熙攘攘的 {argument name=\"city background\" default=\"类似涩谷十字路口的东京街景\"}，伴有行人与霓虹灯。图像采用醒目的排版设计：左侧为巨大的红色竖排日语文字 {argument name=\"left red text\" default=\"新登場\"}，右侧为白色竖排日语文字 {argument name=\"right white text\" default=\"ストリートま上げてく エナジー。\"}，底部边缘有一条纯黄色横幅，上面印有粗体黑色文字 {argument name=\"bottom banner text\" default=\"ENERGY DRINK\"}，旁边配有较小的日语文字以及最右侧的一个小型黑色手部标志。采用动态广角视角，具有浅景深效果。","imgs":["https://r2.qqsrc.com/images/originals/14021.jpg"]},{"i":7382,"text":"{\n  \"type\": \"三格垂直漫画条\",\n  \"style\": \"带有网点和干净线条的黑白动漫风格\",\n  \"character\": \"{argument name=\\\"character description\\\" default=\\\"戴猫耳、短发、穿着简单 T 恤的动漫女孩\\\"}\",\n  \"setting\": \"坐在电脑显示器和键盘前的桌子旁\",\n  \"layout\": {\n    \"panels\": [\n      {\n        \"position\": \"顶部\",\n        \"action\": \"手托下巴，兴奋地看着显示器，带有闪光特效\",\n        \"text_elements\": [\n          {\n            \"type\": \"矩形文本框\",\n            \"position\": \"右上角\",\n            \"text\": \"{argument name=\\\"panel 1 context text\\\" default=\\\"当新的 AI 发布时\\\"}\"\n          },\n          {\n            \"type\": \"对话气泡\",\n            \"position\": \"左侧\",\n            \"text\": \"哇哦哦哦！一定要试试看\"\n          }\n        ]\n      },\n      {\n        \"position\": \"中部\",\n        \"action\": \"瘫倒在键盘上，看起来很累但仍盯着屏幕\",\n        \"text_elements\": [\n          {\n            \"type\": \"对话气泡\",\n            \"position\": \"右侧\",\n            \"text\": \"{argument name=\\\"panel 2 speech text\\\" default=\\\"这到底要持续到什么时候……\\\"}\"\n          },\n          {\n            \"type\": \"对话气泡\",\n            \"position\": \"左侧\",\n            \"text\": \"哇哦哦好厉害\"\n          }\n        ]\n      },\n      {\n        \"position\": \"底部\",\n        \"action\": \"彻底精疲力竭，头平趴在键盘上，半睁着眼，叹着气\",\n        \"text_elements\": [\n          {\n            \"type\": \"对话气泡\",\n            \"position\": \"右侧\",\n            \"text\": \"{argument name=\\\"panel 3 speech text\\\" default=\\\"累死了……\\\"}\"\n          },\n          {\n            \"type\": \"矩形文本框\",\n            \"position\": \"左下角\",\n            \"text\": \"大概还要 5 年吧\"\n          }\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14022.jpg"]},{"i":7383,"text":"{\n  \"type\": \"餐厅促销菜单海报\",\n  \"theme\": \"{argument name=\\\"main ingredient\\\" default=\\\"豆芽\\\"} 主题展\",\n  \"header\": {\n    \"ribbon_text\": \"{argument name=\\\"catchphrase\\\" default=\\\"爽脆口感！\\\"}\",\n    \"main_title\": \"{argument name=\\\"fair title\\\" default=\\\"豆芽主题展\\\"}\",\n    \"sub_text\": \"吃出活力！豆芽让你饱腹满足！\",\n    \"description\": \"选用大量爽脆豆芽，为您呈现本季限定推荐菜单！\",\n    \"background_image\": \"装满新鲜生豆芽的竹篮\"\n  },\n  \"main_dishes\": [\n    {\n      \"image\": \"白底红条纹盘子上的猪肉豆芽韭菜炒菜\",\n      \"badge\": \"蒜香酱油味\",\n      \"name\": \"{argument name=\\\"dish 1 name\\\" default=\\\"豆芽猪肉元气炒菜定食\\\"}\",\n      \"price\": \"¥780 (含税 ¥858)\"\n    },\n    {\n      \"image\": \"黑色碗中盛放的担担面，配有肉末、豆芽、葱花和生蛋黄\",\n      \"badge\": \"香辣肉味噌\",\n      \"name\": \"豆芽满满担担面\",\n      \"price\": \"¥730 (含税 ¥803)\"\n    },\n    {\n      \"image\": \"铁板上滋滋作响的鸡肉豆芽，配有融化的黄油\",\n      \"badge\": \"鸡骨胡椒风味\",\n      \"name\": \"豆芽鸡肉铁板黄油胡椒烧\",\n      \"price\": \"¥680 (含税 ¥748)\"\n    },\n    {\n      \"image\": \"白盘盛放的豆芽炒饭\",\n      \"badge\": \"爽脆口感\",\n      \"name\": \"豆芽炒饭\",\n      \"price\": \"¥590 (含税 ¥649)\"\n    }\n  ],\n  \"bottom_section\": {\n    \"title\": \"搭配享用更划算！超值套餐\",\n    \"set_options_count\": 4,\n    \"options\": [\n      { \"name\": \"饮料吧套餐\", \"image\": \"三种精选饮料\", \"price\": \"+¥220\" },\n      { \"name\": \"沙拉套餐\", \"image\": \"小份绿色沙拉\", \"price\": \"+¥180\" },\n      { \"name\": \"汤品套餐\", \"image\": \"白色杯中的黄色汤品\", \"price\": \"+¥150\" },\n      { \"name\": \"饮料吧 & 沙拉套餐\", \"image\": \"饮料和沙拉\", \"price\": \"+¥350\" }\n    ]\n  },\n  \"footer\": {\n    \"fine_print\": \"※图片仅供参考。※食材产地及内容可能随季节有所变动。※22点后将加收 10% 的深夜服务费。\",\n    \"restaurant_logo\": \"家庭餐厅 {argument name=\\\"restaurant name\\\" default=\\\"Green House\\\"}\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14024.jpg"]},{"i":7384,"text":"{\n  \"type\": \"2x2 数字广告横幅网格\",\n  \"layout\": \"4 个不同的象限，每个象限代表一个不同的行业活动，包含主图、排版和行动号召页脚\",\n  \"quadrants\": [\n    {\n      \"position\": \"左上\",\n      \"industry\": \"护肤美妆\",\n      \"visuals\": \"一位皮肤清透的年轻亚洲女性肖像，漂浮的水珠，精华液瓶和面霜罐\",\n      \"headline\": \"{argument name=\\\"skincare headline\\\" default=\\\"うるおい、透明感、つづく。\\\"}\",\n      \"subtext\": \"从肌底焕发光彩的护肤体验。\",\n      \"badge\": \"敏感肌友好配方\",\n      \"footer\": \"蓝色横条，显示“今だけ数量限定 10%OFF | 送料無料”及“詳しくはこちら →”\"\n    },\n    {\n      \"position\": \"右上\",\n      \"industry\": \"美食外卖\",\n      \"visuals\": \"深色陶瓷盘中浓郁肉酱意面的微距特写，暗调氛围光\",\n      \"headline\": \"{argument name=\\\"food headline\\\" default=\\\"休日は、ちょっといいパスタを。\\\"}\",\n      \"subtext\": \"慢火细炖的纯正博洛尼亚肉酱面\",\n      \"checklist_count\": 3,\n      \"checklist_items\": [\"100% 国产牛肉\", \"无化学调味料\", \"隔水加热仅需 5 分钟\"],\n      \"badge\": \"金色圆圈“初回限定 20%OFF 送料無料”\",\n      \"footer\": \"深红色横条，显示“ご注文はこちら →”\"\n    },\n    {\n      \"position\": \"左下\",\n      \"industry\": \"旅游观光\",\n      \"visuals\": \"郁郁葱葱的森林，清澈的蓝色河流，背景是蓝天下的雪山\",\n      \"headline\": \"{argument name=\\\"travel headline\\\" default=\\\"まだ見ぬ、日本に会いに行く。\\\"}\",\n      \"subtext\": \"来一场让心灵悸动的旅行。\",\n      \"badge\": \"黄色圆圈“最大 30% OFF”\",\n      \"footer\": \"青色横条，显示“今だけお得！ 早割キャンペーン実施中”及“特設サイトはこちら →”\"\n    },\n    {\n      \"position\": \"右下\",\n      \"industry\": \"健身房\",\n      \"visuals\": \"一位身穿黑色运动装的年轻亚洲女性在昏暗的健身房内使用器械锻炼\",\n      \"headline\": \"{argument name=\\\"gym headline\\\" default=\\\"ジブン史上、最高のカラダへ。\\\"}\",\n      \"subtext\": \"成就最好的自己。\",\n      \"feature_boxes_count\": 3,\n      \"feature_boxes\": [\"24 小时开放\", \"新手友好支持\", \"完善的训练设施\"],\n      \"footer\": \"亮黄色横条，显示“{argument name=\\\"gym offer\\\" default=\\\"今なら入会金 0円 + 初月会費 50%OFF\\\"}”及“無料体験はこちら →”\"\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14026.jpg"]},{"i":7385,"text":"{\n  \"type\": \"化妆品促销网页横幅\",\n  \"subject\": {\n    \"description\": \"一位面带微笑的年轻东亚女性，皮肤光泽水润，身穿简约白色背心，头发扎起并留有几缕碎发。她右手轻触右脸颊，左手拿着一个 {argument name=\\\"product type\\\" default=\\\"透明精华液按压瓶\\\"} 靠近面部。\"\n  },\n  \"background\": \"柔和、模糊且明亮的梳妆台背景，带有闪烁的焦外成像和光晕效果。\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"position\": \"左上角\",\n        \"type\": \"主标题\",\n        \"text\": \"{argument name=\\\"main headline\\\" default=\\\"护肤迷茫的懒人必看！\\\"}\"\n      },\n      {\n        \"position\": \"左中部\",\n        \"type\": \"副标题\",\n        \"text\": \"{argument name=\\\"sub headline\\\" default=\\\"连我这种懒人都能坚持每天用的导入精华，强力推荐！！\\\"}\"\n      },\n      {\n        \"position\": \"左侧中心\",\n        \"type\": \"要点列表\",\n        \"count\": 3,\n        \"style\": \"红色勾选标记\",\n        \"labels\": [\n          \"洁面后只需用它！\",\n          \"后续化妆水吸收力加倍\",\n          \"打造水光肌！妆容更服帖\"\n        ]\n      },\n      {\n        \"position\": \"左下角\",\n        \"type\": \"产品试用装\",\n        \"elements\": [\n          {\n            \"description\": \"带有丝带的金色圆形徽章\",\n            \"text\": \"{argument name=\\\"badge text\\\" default=\\\"4 天试用\\\"}\"\n          },\n          {\n            \"description\": \"小型试用装瓶组\",\n            \"count\": 4\n          }\n        ]\n      },\n      {\n        \"position\": \"底部中心\",\n        \"type\": \"行动号召\",\n        \"text\": \"{argument name=\\\"call to action\\\" default=\\\"快来试试吧！4 天试用套装\\\"}\",\n        \"style\": \"发光下划线\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14027.jpg"]},{"i":7386,"text":"一张年轻男子的写实风格自拍，他留着深色短卷发，留着浅浅的胡茬，身处室内篮球场。他穿着一件带有白色耐克勾标志的黑色运动 T 恤。他手中拿着一个 {argument name=\"ball color\" default=\"绿色\"} 篮球，上面印有一个醒目的白色 {argument name=\"logo design\" default=\"OpenAI logo\"}。背景展示了硬木地板、黑色墙垫以及混凝土墙上的篮球架。明亮的室内健身房灯光，呈现出休闲的社交媒体美学。","imgs":["https://r2.qqsrc.com/images/originals/14028.jpg"]},{"i":7387,"text":"{\n  \"type\": \"2x2 日式广告横幅网格\",\n  \"layout\": {\n    \"grid\": \"2 行 2 列\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"industry\": \"化妆品\",\n        \"visuals\": \"一位年轻亚洲女性的特写肖像，皮肤透亮，正轻轻触碰脸颊。左下角放置 2 款护肤品：一个磨砂质感的高瓶和一罐短小的面霜，标签为“{argument name=\"skincare brand\" default=\"SUIREN\"}”。\",\n        \"typography\": \"醒目的竖排日文“透明感、満ちる。”和“肌が変わると、毎日が変わる。”。圆形徽章“6.1 NEW Debut”。底部标注品牌名“SUIREN”。\"\n      },\n      {\n        \"position\": \"右上\",\n        \"industry\": \"旅游\",\n        \"visuals\": \"一位戴着草帽、身穿白衬衫的女性背影，正眺望着风景优美的“{argument name=\"travel destination\" default=\"欧洲湖畔小镇\"}”，背景是山脉和教堂尖顶。天空中有一架小型飞机插画。\",\n        \"typography\": \"手写体“Find your Journey”。醒目的白色日文“心が動く旅へ。”。黄色圆形徽章“今だけ！最大20%OFF 6.30まで”。深蓝色底部栏写有“初夏のヨーロッパキャンペーン”及“詳しくはこちら >”按钮。\"\n      },\n      {\n        \"position\": \"左下\",\n        \"industry\": \"食品\",\n        \"visuals\": \"一碗质朴的白米饭，上面放着一颗橙红色的生蛋黄和鲣鱼干。深色酱汁正从一个小壶中淋下。左下角是一个带有蓝色波浪图案的棕色纸包装，内装“{argument name=\"food product\" default=\"出汁粉\"}”。\",\n        \"typography\": \"竖排日文“毎日のごはんを、もっと美味しく。”。产品名称“日々のだし”采用大号衬线字体。小徽章“だしパック 30袋入”。\"\n      },\n      {\n        \"position\": \"右下\",\n        \"industry\": \"科技\",\n        \"visuals\": \"一部现代智能手机，屏幕显示“{argument name=\"app type\" default=\"金融投资\"}”仪表盘，包含上升趋势的折线图和投资组合细分。一个蓝色礼盒图标。\",\n        \"typography\": \"App Logo“M {argument name=\"app name\" default=\"MoneyPath\"}”。标题“未来の自分のために、今はじめる資産形成”。蓝色圆形徽章“新規登録で1,000円分のポイントプレゼント！”。蓝色底部栏分为 4 列，包含图标和文字，如“100円からはじめられる”和“NISAにも対応”。\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14031.jpg"]},{"i":7388,"text":"一张写实风格的场景图，展示了一枚巨大的金属火箭在 {argument name=\"setting\" default=\"种有棕榈树的住宅区\"} 上方极低的高度水平悬停。银色航天器的侧面清晰地显示着 {argument name=\"company name\" default=\"SPACEX\"} 字样。尾部引擎喷射出明亮的橙色火焰和浓烟。前景是深色的混凝土屋顶，背景是在朦胧的 {argument name=\"lighting\" default=\"日落\"} 光线下，掩映在热带植被中的小型多层建筑，营造出先进航天科技与日常生活之间超现实的并置感。","imgs":["https://r2.qqsrc.com/images/originals/14033.jpg"]},{"i":7389,"text":"{\n  \"type\": \"2x2 广告横幅网格\",\n  \"layout\": {\n    \"grid_size\": \"2x2\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"industry\": \"护肤\",\n        \"visuals\": \"一位皮肤光泽、留着黑色短发、身穿白色吊带背心的年轻亚洲女性，手轻轻触碰脸庞。左下角有 3 瓶白色化妆品。\",\n        \"typography\": {\n          \"main_copy\": \"{argument name=\\\"skincare catchphrase\\\" default=\\\"素肌が、いちばんのメイクになる。\\\"}\",\n          \"sub_copy\": \"肌本来の力を引き出す 新・スキンケアシリーズ誕生\",\n          \"badge\": \"4.25 NEW DEBUT\",\n          \"brand_name\": \"urala\",\n          \"tagline\": \"うららかに、わたしらしく。\"\n        }\n      },\n      {\n        \"position\": \"右上\",\n        \"industry\": \"咖啡馆\",\n        \"visuals\": \"窗边的木桌，盘子里放着果酱和黄油吐司，一杯黑咖啡，以及刀叉。\",\n        \"typography\": {\n          \"top_text\": \"森のそばの小さなカフェ\",\n          \"main_copy\": \"{argument name=\\\"cafe catchphrase\\\" default=\\\"今日も、いい日。\\\"}\",\n          \"sub_copy\": \"こだわりのコーヒーと、焼きたてのパンでほっとひと息しませんか？\",\n          \"badge\": \"季節限定 いちごのジャムトースト始めました\",\n          \"logo\": \"morino cafe\",\n          \"details\": \"OPEN 8:00 - 18:00 定休日: 水曜日 〒150-0001 東京都渋谷区神宮前 1-2-3\"\n        }\n      },\n      {\n        \"position\": \"左下\",\n        \"industry\": \"健身房\",\n        \"visuals\": \"一位身穿黑色运动内衣、扎着马尾辫的亚洲女性运动员，正在流汗，神情坚定。背景为带有紫色霓虹灯的健身房。\",\n        \"typography\": {\n          \"top_text\": \"今こそ、理想の自分へ\",\n          \"main_copy\": \"{argument name=\\\"gym catchphrase\\\" default=\\\"わたしを、超えていけ。\\\"}\",\n          \"bullet_points\": [\n            \"☑ パーソナルトレーニング\",\n            \"☑ 初心者サポート充実\",\n            \"☑ 手ぶらでOK\"\n          ],\n          \"offer\": \"まずは体験から！ 体験トレーニング 60分 {argument name=\\\"gym price\\\" default=\\\"¥2,200\\\"}(税込)\",\n          \"logo\": \"B BEYOND LIMIT PERSONAL GYM\"\n        }\n      },\n      {\n        \"position\": \"右下\",\n        \"industry\": \"旅游度假\",\n        \"visuals\": \"无边泳池与湛蓝的大海融为一体，白色躺椅，晴朗的天空，盆栽植物。\",\n        \"typography\": {\n          \"main_copy\": \"{argument name=\\\"resort catchphrase\\\" default=\\\"まだ見ぬ景色に、出会う旅。\\\"}\",\n          \"sub_copy\": \"心がほどける、特別な時間をあなたに。\",\n          \"logo\": \"UMI to SORA RESORT\",\n          \"bottom_bar\": \"＼ 期間限定 ／ 夏のご予約キャンペーン 最大 20% OFF ご予約は公式サイトから → 2024.6.1 sat - 7.31 wed\",\n          \"elements\": [\n            \"二维码\"\n          ]\n        }\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14035.jpg"]},{"i":7390,"text":"{\n  \"type\": \"直播 UI 样机\",\n  \"subject\": {\n    \"description\": \"{argument name=\\\"host name\\\" default=\\\"Elon Musk\\\"} 的肖像，面带微笑，身穿印有白色技术示意图的黑色 T 恤\",\n    \"background\": \"左侧显示带有 '{argument name=\\\"left background logo\\\" default=\\\"SPACEX\\\"}' 文字的屏幕，右侧显示红色的 '{argument name=\\\"right background logo\\\" default=\\\"Tesla T logo\\\"}' 和一辆深色汽车\"\n  },\n  \"ui_overlay\": {\n    \"top_header\": {\n      \"host_info\": \"头像，名称 '{argument name=\\\"host name\\\" default=\\\"Elon Musk\\\"}'，副标题 '55.6万本场点赞'，红色 '关注' 按钮\",\n      \"rank_badge\": \"带有 '全站第1名' 的金币图标\",\n      \"viewer_stats\": \"3 个顶部观众头像，显示 '12.3w'、'8.6w'、'5.7w'，总计 '68.7万'，'X' 关闭按钮\",\n      \"right_links\": \"'更多直播 >'，'礼物展馆 0/24'（带有蓝色 '经典' 标签）\"\n    },\n    \"mid_left_gifts\": {\n      \"count\": 2,\n      \"items\": [\n        \"头像 '科技爱好者'，'送小心心'，爱心图标 x 1314\",\n        \"头像 '星辰大海'，'送火箭'，火箭图标 x 666\"\n      ]\n    },\n    \"bottom_left_chat\": {\n      \"system_message\": \"37 级勋章 '宇宙漫游者 加入了直播间'\",\n      \"message_count\": 7,\n      \"messages\": [\n        \"小火箭: 马斯克！未来可期！🚀\",\n        \"future: 特斯拉Model 2什么时候出？\",\n        \"星空梦想家: SpaceX今年能上火星吗？\",\n        \"AI探索者: Neuralink进展如何？\",\n        \"帅气的网友: 马总好！\",\n        \"Mars: 第一次来你的直播，超激动！\",\n        \"用户123: 讲讲AI吧，会取代人类吗？\"\n      ]\n    },\n    \"bottom_right_product_card\": {\n      \"hot_tag\": \"橙色 '热卖 x 1888'\",\n      \"image\": \"Tesla Cybertruck\",\n      \"title\": \"{argument name=\\\"product name\\\" default=\\\"特斯拉Cybertruck 电动皮卡\\\"}\",\n      \"price\": \"{argument name=\\\"product price\\\" default=\\\"¥ 1,618,000\\\"}\",\n      \"button\": \"红色 '抢' 按钮\",\n      \"floating_animation\": \"半透明爱心沿右侧边缘向上浮动\"\n    },\n    \"bottom_bar\": {\n      \"input_field\": \"'说点什么...'\",\n      \"icons\": [\"笑脸\", \"三个点\", \"购物车\", \"礼物盒\", \"分享\"]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14036.jpg"]},{"i":7391,"text":"{\n  \"type\": \"日剧电影海报\",\n  \"style\": \"电影摄影风格，情感充沛，柔和的黄金时刻光影\",\n  \"layout\": {\n    \"main_poster_area\": {\n      \"visuals\": {\n        \"right\": \"身穿水手服的年轻日本女性侧脸大特写，神情忧郁\",\n        \"center\": \"抬头仰望的柴犬\",\n        \"left\": \"站在沿海公路上的中年日本男性\",\n        \"background\": \"日落时的海岸线，天空中飞翔的鸟群\"\n      },\n      \"typography\": {\n        \"title\": \"{argument name=\\\"movie title\\\" default=\\\"夕凪のしっぽ\\\"}\",\n        \"subtitle\": \"——あの日のきみへ——\",\n        \"right_copy\": \"{argument name=\\\"right tagline\\\" default=\\\"きみがくれた時間が、わたしを変えていった。\\\"}\",\n        \"left_copy\": \"失ったものは戻らない。それでも誰かと心を通わせることで、人はもう一度前を向ける。\",\n        \"date\": \"{argument name=\\\"release date\\\" default=\\\"10.31 FRI.\\\"}\\nROADSHOW\",\n        \"credits\": \"{argument name=\\\"credits text\\\" default=\\\"主演: 福波摩子 / 霧峰周作\\\"}\"\n      }\n    },\n    \"bottom_stills_strip\": {\n      \"count\": 5,\n      \"panels\": [\n        \"女孩坐在海滩上面对柴犬\",\n        \"女孩骑着自行车望向港口\",\n        \"女孩和男子坐在室内桌旁，柴犬在桌下\",\n        \"男子和女孩在海滩上保持距离站立\",\n        \"女孩拥抱柴犬的特写\"\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14038.jpg"]},{"i":7392,"text":"一张电影级、照片级逼真的镜头，画面中是一位年轻女性，留着 {argument name=\"hair style\" default=\"带有小辫子的长波浪棕色头发\"}，身穿 {argument name=\"clothing style\" default=\"带有毛皮镶边和皮革小袋的乡村风格厚重历史服饰\"}。她跪在雪地里，温柔地拥抱着一只巨大的、温顺的 {argument name=\"animal type\" default=\"棕色灰熊\"}。女子和熊都闭着眼睛，沉浸在宁静而深情的拥抱中。熊将它巨大的头靠在女子身上。背景是冬日的 {argument name=\"environment\" default=\"雪中松林\"}，光线柔和自然。细小的雪花散落在女子的头发和熊厚实的皮毛上。高细节，8k 分辨率，奇幻写实风格。","imgs":["https://r2.qqsrc.com/images/originals/14040.jpg"]},{"i":7393,"text":"{\n  \"type\": \"日式饮品广告横幅\",\n  \"subject\": {\n    \"description\": \"年轻日本女性，笑容温暖，注视着观众，身穿白色衬衫，手持一罐啤酒。\",\n    \"speech_bubble\": \"{argument name=\\\"speech bubble text\\\" default=\\\"今日のごほうびに、この一杯！\\\"}\"\n  },\n  \"product\": {\n    \"name\": \"{argument name=\\\"product name\\\" default=\\\"PREMIUM LAGER\\\"}\",\n    \"packaging\": \"带有啤酒花图案和蓝色文字的白金配色啤酒罐\"\n  },\n  \"layout\": {\n    \"background\": \"柔和、明亮、虚化的户外绿植背景\",\n    \"sections\": [\n      {\n        \"position\": \"左上角\",\n        \"type\": \"宣传标语\",\n        \"text\": [\n          \"{argument name=\\\"main catchphrase\\\" default=\\\"新しいおいしさ、できました。\\\"}\",\n          \"{argument name=\\\"secondary catchphrase\\\" default=\\\"爽やかに香る、キレのあるうまさ！\\\"}\"\n        ]\n      },\n      {\n        \"position\": \"中左侧\",\n        \"type\": \"产品品牌\",\n        \"main_text\": \"{argument name=\\\"product name\\\" default=\\\"PREMIUM LAGER\\\"}\",\n        \"sub_text\": \"プレミアムラガー\",\n        \"badges\": [\"新発売\", \"麦芽100%\"],\n        \"graphics\": \"金色啤酒花插图\"\n      },\n      {\n        \"position\": \"中左侧下方\",\n        \"type\": \"产品亮点\",\n        \"count\": 3,\n        \"style\": \"带图标的圆角矩形框\",\n        \"items\": [\n          {\"icon\": \"hop\", \"text\": \"华丽香气，使用香气啤酒花\"},\n          {\"icon\": \"water drop\", \"text\": \"清爽怡人，回味干脆\"},\n          {\"icon\": \"wheat\", \"text\": \"100% 麦芽，口感醇厚\"}\n        ]\n      },\n      {\n        \"position\": \"底部\",\n        \"type\": \"促销横幅\",\n        \"background_color\": \"深蓝色\",\n        \"main_text\": \"新・プレミアムラガー、誕生。\",\n        \"campaign_box\": {\n          \"badge\": \"抽奖赢好礼！\",\n          \"text\": \"{argument name=\\\"campaign text\\\" default=\\\"コンビニ無料引換券 抽選キャンペーンはこちら >\\\"}\",\n          \"element\": \"二维码\"\n        },\n        \"footer\": \"法定饮酒年龄警告及回收标志\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14041.jpg"]},{"i":7394,"text":"{\n  \"type\": \"真人电影海报与综合角色参考图\",\n  \"layout\": {\n    \"top_half\": {\n      \"type\": \"电影感海报\",\n      \"visuals\": \"前景为抱着橘色虎斑猫的年轻日本男性，背景为看向右侧的年轻日本女性，背景是带有桥梁和淡淡彩虹的黄金时刻城市天际线。\",\n      \"typography\": {\n        \"title\": \"{argument name=\\\"movie title\\\" default=\\\"虹の橋の約束\\\"}\",\n        \"subtitle\": \"NIJI NO HASHI NO YAKUSOKU\",\n        \"release_date\": \"{argument name=\\\"release date\\\" default=\\\"11.7 FRI roadshow\\\"}\",\n        \"taglines\": \"多处垂直与水平排列的日语文本块。\"\n      }\n    },\n    \"middle_band\": {\n      \"type\": \"胶片条\",\n      \"count\": 5,\n      \"description\": \"由 5 张展示角色在不同场景下的电影剧照组成的水平行。\"\n    },\n    \"bottom_half\": {\n      \"type\": \"角色设计图\",\n      \"sections\": [\n        {\n          \"subject\": \"女性角色\",\n          \"name\": \"{argument name=\\\"female character name\\\" default=\\\"藤木 ハル\\\"}\",\n          \"full_body_poses\": 4,\n          \"pose_labels\": [\"正面\", \"侧面 (左)\", \"背面\", \"3/4 侧面\"],\n          \"facial_expressions\": 3,\n          \"detail_shots\": 3,\n          \"footwear_angles\": 3,\n          \"silhouette_postures\": 2,\n          \"color_swatches\": 5\n        },\n        {\n          \"subject\": \"男性角色\",\n          \"name\": \"{argument name=\\\"male character name\\\" default=\\\"瀬川 凛\\\"}\",\n          \"full_body_poses\": 4,\n          \"pose_labels\": [\"正面\", \"侧面 (左)\", \"背面\", \"3/4 侧面\"],\n          \"facial_expressions\": 3,\n          \"detail_shots\": 3,\n          \"footwear_angles\": 3,\n          \"silhouette_postures\": 2\n        },\n        {\n          \"subject\": \"橘色虎斑猫\",\n          \"name\": \"{argument name=\\\"cat name\\\" default=\\\"チェリー\\\"}\",\n          \"full_body_poses\": 3,\n          \"large_headshot\": 1,\n          \"small_headshots\": 4,\n          \"detail_shots\": 3,\n          \"color_swatches\": 4,\n          \"scale_reference\": 1\n        },\n        {\n          \"subject\": \"额外剧照\",\n          \"count\": 6,\n          \"description\": \"由 6 张展示角色与猫的电影剧照组成的网格。\"\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14042.jpg"]},{"i":7395,"text":"一张写实的高分辨率商业摄影图片，前景是一辆 {argument name=\"car model and color\" default=\"亮蓝色 Alpine A110 R 跑车\"}，停在巨大的飞机库内。跑车配有黑色碳纤维引擎盖、黑色车顶、黑色合金轮毂，前车牌上写着 \"{argument name=\"license plate text\" default=\"A110 R\"}\"。在车后方，背景中是一架占据视觉中心的 {argument name=\"airplane model\" default=\"白色空客 A320 商用客机\"}，机尾为蓝色。机库地面为高度抛光的反光混凝土，映照出跑车和飞机的倒影。左侧金属墙上的标志写着 \"{argument name=\"hangar sign text\" default=\"HANGAR 05 MAINTENANCE\"}\"。机库大门敞开，露出明亮的阴天和远处的城市景观。光线柔和且具有电影质感，突显了两种交通工具流畅的空气动力学曲线。","imgs":["https://r2.qqsrc.com/images/originals/14043.jpg"]},{"i":7396,"text":"一张从昏暗的大学阶梯教室观众席拍摄的写实照片，镜头越过前景中三名学生的后脑勺，望向巨大的投影屏幕。投影屏幕呈现出分为三个独立垂直面板的布局。左侧面板显示垂直的 {argument name=\"left game\" default=\"地铁跑酷游戏画面\"}，画面中一个角色在铁轨上奔跑并收集金币，带有显示分数为 \"001022\" 的 UI 元素。宽大的中央面板显示一张学术演示 Slides，标题为 \"{argument name=\"slide topic\" default=\"9.3：无穷几何级数\"}\"。幻灯片包含数学文本：\"例 3：求无穷几何级数的和。1/3 - 1/9 + 1/27 - 1/81 + ... 解：该级数为几何级数，其中 a = 1/3 且 r = -1/3。由于 |r| < 1，该无穷几何级数收敛。S = a / (1 - r) = (1/3) / (1 - (-1/3)) = (1/3) / (4/3) = 1/4。级数之和为 1/4。\" 幻灯片页脚显示 \"{argument name=\"professor name\" default=\"Larson 博士\"}\"、\"{argument name=\"course name\" default=\"微积分 II\"}\"、\"2024 年 11 月 14 日\" 以及 \"7 / 35\"。右侧面板显示垂直的 {argument name=\"right game\" default=\"我的世界跑酷游戏画面\"}，展示了草地景观上方的浮动木块，右下角带有 TikTok 水印。房间装有吊顶，屏幕边缘后方可见黑板。","imgs":["https://r2.qqsrc.com/images/originals/14047.jpg"]},{"i":7397,"text":"{\n  \"type\": \"综合信息图表说明表\",\n  \"style\": \"{argument name=\\\"illustration style\\\" default=\\\"扁平矢量动漫风格\\\"}\",\n  \"color_palette\": \"{argument name=\\\"color palette\\\" default=\\\"米色背景，搭配深棕色、红色和蓝色点缀\\\"}\",\n  \"layout\": {\n    \"header\": {\n      \"tag\": \"中国电视剧《狂飙》观剧指南\",\n      \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"如何更深入地欣赏《狂飙》\\\"}\",\n      \"subtitle\": \"了解作品背后的社会背景，让故事变得更深刻、更真实！\",\n      \"top_right_badge\": \"善与恶、光与影交织的硬核悬疑剧！\"\n    },\n    \"sections\": [\n      {\n        \"number\": 1,\n        \"title\": \"《狂飙》制作背景：什么是“政法委”与“扫黑除恶”\",\n        \"components\": [\n          {\"type\": \"bulleted text\", \"description\": \"政治术语定义\"},\n          {\"type\": \"diagram\", \"description\": \"两个重叠的圆圈，分别标注为“反腐败”和“扫黑除恶”\"},\n          {\"type\": \"illustration\", \"description\": \"两名男性的侧面相对形象；一人身穿警服，一人身穿深色西装并系红色领带\"}\n        ]\n      },\n      {\n        \"number\": 2,\n        \"title\": \"“扫黑/反腐剧”这一类型\",\n        \"components\": [\n          {\"type\": \"illustration\", \"description\": \"4 名角色（3 男 1 女）站在红色横幅后的阵容\"},\n          {\"type\": \"checklist\", \"count\": 3, \"description\": \"剧集走红的原因，配有绿色勾选标记\"},\n          {\"type\": \"illustration\", \"description\": \"一名警察向上指并带有对话气泡\"}\n        ]\n      },\n      {\n        \"number\": 3,\n        \"title\": \"时代背景：GDP 增长约 15 倍的经济飞速发展\",\n        \"components\": [\n          {\"type\": \"chart\", \"chart_type\": \"{argument name=\\\"chart type\\\" default=\\\"比较两个趋势随时间变化的折线图\\\"}\", \"description\": \"1990 年至 2022 年中国与日本的 GDP 对比\"},\n          {\"type\": \"timeline\", \"count\": 3, \"description\": \"城市演变过程：1998 年村庄、2006 年工厂、2020 年现代化高楼城市\"}\n        ]\n      },\n      {\n        \"number\": 4,\n        \"title\": \"地方政府权力关系：职务解析\",\n        \"components\": [\n          {\"type\": \"flowchart\", \"topic\": \"{argument name=\\\"flowchart topic\\\" default=\\\"地方政府权力结构\\\"}\", \"description\": \"3x3 网格，展示国家、省、市三级在党、政、法系统中的架构\"},\n          {\"type\": \"illustration\", \"description\": \"一名身穿深色夹克的男子向前看，配有解释其角色的文字\"}\n        ]\n      }\n    ],\n    \"footer\": {\n      \"text\": \"了解背景后，人物的言行与社会动态将显得更加真实。请尽情深入探索《狂飙》的世界吧！\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14048.jpg"]},{"i":7398,"text":"{\"type\": \"直播界面模型\", \"layout\": {\"main_feed\": {\"content\": \"电子游戏场景，牛仔剪影在日落时分凝视着带有凯尔特十字架的墓碑\", \"subtitle\": \"{argument name=\\\"game subtitle\\\" default=\\\"Arthur I gave you all I had.\\\"}\", \"ui_elements\": [\"左下角的圆形小地图\"]}, \"webcam\": {\"position\": \"左上角\", \"subject\": \"{argument name=\\\"webcam subject\\\" default=\\\"Sam Altman\\\"} 神情专注且略显忧伤\", \"background\": \"带有植物和发光台灯的房间\"}, \"stream_info\": {\"position\": \"底部\", \"profile\": {\"name\": \"{argument name=\\\"streamer name\\\" default=\\\"SamAltman\\\"}\", \"verified\": true, \"avatar\": \"主播的灰度肖像\", \"live_badge\": \"直播中\"}, \"details\": {\"title\": \"{argument name=\\\"stream title\\\" default=\\\"first playthrough of RDR2 (no spoilers please!)\\\"}\", \"category\": \"{argument name=\\\"game title\\\" default=\\\"Red Dead Redemption 2\\\"}\", \"tags\": [\"英语\", \"AMA\", \"OpenAI\", \"CEO\", \"人工智能\"]}, \"stats\": {\"viewers\": \"141,572\", \"uptime\": \"3:42:17\"}, \"buttons\": [\"关注\", \"订阅\"]}, \"chat_sidebar\": {\"position\": \"右侧\", \"header\": \"直播聊天\", \"messages_count\": 17, \"message_examples\": [\"spaghetti_code: 别哭\", \"nicodemus88: 我们都会成功的\", \"quantumlance: 巅峰之作\", \"souljaboytellem: 腰痛 (LUMBAGO)\", \"m4xw311: 骑行高地，牛仔\"], \"input_area\": \"带有紫色“发送”按钮的消息输入框\"}}}","imgs":["https://r2.qqsrc.com/images/originals/14049.jpg"]},{"i":7399,"text":"{\n  \"type\": \"黑暗奇幻背景设定信息图\",\n  \"style\": \"哥特蒸汽朋克动漫艺术风格，深色背景，配有精致的金色和青铜色华丽边框及文字\",\n  \"header\": {\n    \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"《诡秘之主》\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"塔罗会全览图\\\"}\",\n    \"english_subtitle\": \"THE TAROT CLUB\",\n    \"sub_subtitle\": \"愚者的序列，世界的真相\"\n  },\n  \"top_panels\": [\n    { \"title\": \"塔罗会简介\", \"position\": \"top-left\", \"illustration\": \"栖息在树枝上的乌鸦\" },\n    { \"title\": \"核心信条\", \"position\": \"top-right\", \"illustration\": \"眼睛与太阳徽章\", \"content_type\": \"项目符号列表\" }\n  ],\n  \"centerpiece\": {\n    \"title\": \"{argument name=\\\"center character title\\\" default=\\\"0 愚者 THE FOOL\\\"}\",\n    \"name\": \"{argument name=\\\"center character name\\\" default=\\\"克莱恩·莫雷蒂\\\"}\",\n    \"english_name\": \"Klein Moretti\",\n    \"illustration\": \"一幅高度精细的大型肖像，描绘了一位身着深色西装领带、坐在华丽高背椅上、神情神秘的英俊青年\",\n    \"details\": \"肖像下方的文本框，列出途径、序列、关键词和描述\"\n  },\n  \"orbiting_characters\": {\n    \"count\": 9,\n    \"layout\": \"以圆形星座图案排列在中心人物周围，由细金线和小型圆形节点连接\",\n    \"labels\": [\n      \"XI 正义 JUSTICE / 迟暮女士 Dame Hastur\",\n      \"XII 倒吊人 THE HANGED MAN / 阿蒙 Amon\",\n      \"XIX 太阳 THE SUN / “小丑” Terry\",\n      \"I 魔术师 THE MAGICIAN / “冠位” Dunn Smith\",\n      \"XXI 世界 THE WORLD / 安塞尔 Ansel\",\n      \"IX 隐者 THE HERMIT / 奥黛丽 Audrey Hall\",\n      \"XVII 星星 THE STAR / 拉塞尔 Russell\",\n      \"XX 审判 JUDGEMENT / 阿尔杰农 Algernon\",\n      \"XVIII 月亮 THE MOON / 贝克兰德 Blau Bachland\"\n    ],\n    \"card_structure\": \"每个部分包含一张小型矩形动漫肖像、罗马数字、塔罗牌名称、角色名称和属性文本\"\n  },\n  \"connection_legend\": {\n    \"count\": 5,\n    \"labels\": [\"情报贡献\", \"战斗支援\", \"资源支持\", \"信仰链接\", \"外部联系\"]\n  },\n  \"bottom_panels\": [\n    { \"title\": \"塔罗会会议\", \"position\": \"bottom-left\", \"illustration\": \"一群披着斗篷的身影坐在黑暗中烛光摇曳的桌子旁\" },\n    { \"title\": \"所属途径统计\", \"position\": \"bottom-center\", \"content\": \"10 条途径列表，配有中央罗盘星徽章\" },\n    { \"title\": \"核心目标\", \"position\": \"bottom-right\", \"illustration\": \"哥特式城堡剪影\", \"content_type\": \"项目符号列表\" }\n  ],\n  \"footer_symbols\": {\n    \"title\": \"象征与信物\",\n    \"count\": 10,\n    \"labels\": [\"塔罗牌\", \"怀表\", \"单片眼镜\", \"乌鸦\", \"灰雾\", \"秘银匕首\", \"青铜长桌\", \"高背椅\", \"门扉\", \"星图\"]\n  },\n  \"footer_quote\": \"{argument name=\\\"footer quote\\\" default=\\\"当愚者端坐于高背椅之上，塔罗牌的命运便已洗牌。\\\"} ——《诡秘之主》\"\n}","imgs":["https://r2.qqsrc.com/images/originals/14050.jpg"]}];